const PERMITIDAS = new Set(['pdf', 'png', 'jpg'])
const TAMANHO_MAXIMO = 10485760

function validarUpload(entrada) {
  const nome = String(entrada?.nome ?? '')

  if (nome.includes('/') || nome.includes('\\') || nome.includes('..')) {
    return { ok: false, motivo: 'nome inválido' }
  }

  const extensao = nome.split('.').pop()?.toLowerCase() ?? ''
  if (!PERMITIDAS.has(extensao)) {
    return { ok: false, motivo: 'tipo não permitido' }
  }

  if (!Number.isFinite(entrada.tamanho) || entrada.tamanho > TAMANHO_MAXIMO) {
    return { ok: false, motivo: 'arquivo muito grande' }
  }

  return { ok: true, nomeSeguro: `arquivo.${extensao}` }
}

