function podeExecutar(matriz, usuario, acao, recurso) {
  const acoes = matriz?.[usuario?.papel] ?? []
  if (!acoes.includes(acao)) return false

  // A matriz responde pelo papel; a propriedade do recurso e outra pergunta.
  if (acao.endsWith(':proprio')) {
    if (!recurso) return false
    return recurso.donoId === usuario.id
  }

  return true
}

