function detectarVarredura(eventos, limite, janelaSegundos) {
  const porUsuario = new Map()

  for (const evento of eventos ?? []) {
    if (evento.tipo !== 'acesso_negado') continue
    const instantes = porUsuario.get(evento.usuarioId) ?? []
    instantes.push(evento.em)
    porUsuario.set(evento.usuarioId, instantes)
  }

  const suspeitos = []

  for (const [usuarioId, instantes] of porUsuario) {
    instantes.sort((a, b) => a - b)

    // Janela deslizante: basta olhar o evento `limite - 1` posicoes a frente.
    for (let i = 0; i + limite - 1 < instantes.length; i += 1) {
      if (instantes[i + limite - 1] - instantes[i] <= janelaSegundos) {
        suspeitos.push(usuarioId)
        break
      }
    }
  }

  return suspeitos.sort((a, b) => a - b)
}
